'use strict';
const officeDefaults={assets:[{id:'home',name:'Your home',market:850000,mortgage:350000,primary:true}],policies:{global:{mode:'reinvest',until:'2036-10-17'},bonds:{mode:'income',until:''},isa:{mode:'reinvest',until:'2031-10-17'}},officePlansSeeded:false};Object.assign(defaults,structuredClone(officeDefaults));
function ensureOffice(){ensurePlanner();for(const [k,v] of Object.entries(officeDefaults))if(state[k]===undefined)state[k]=structuredClone(v)}ensureOffice();
function modellingContext(){return {usedISA:ledger.allowances.isa,usedEIS:ledger.allowances.eis,usedCGT:ledger.allowances.cgt,loanPrincipal:ledger.loans.filter(l=>l.borrower==='fic').reduce((a,l)=>a+l.balance,0),sources:[...cashPositions().filter(p=>['cash','ficcash'].includes(p.id)).map(p=>({id:p.id,name:p.name,owner:p.owner==='household'?'personal':'company',kind:'cash',balance:available(p.id),price:1,gainRatio:0})),...['gia','global'].map(id=>{const p=ledger.positions.find(x=>x.id===id);return{id,name:p.name+(id==='gia'?' · personal account':' · company account'),owner:id==='gia'?'personal':'company',kind:'sale',balance:value(p),price:p.price,gainRatio:Math.max(0,(value(p)-p.cost)/value(p))}})]}}
const oldCompareRoutesOffice=compareRoutes;compareRoutes=p=>investmentRoutes({...p,date:p.date||today},modellingContext());chooseScenario=(c,p)=>preferredRoute(c,p);
function newPlanObject(p,stage='Planned'){const scenario=chooseScenario(compareRoutes(p),p);return {...structuredClone(p),id:crypto.randomUUID(),name:p.name||(p.type==='fund'?'Fund investment':'Investment plan'),version:1,stage,status:stage,scenario,steps:executionSteps(scenario,p),partnerNotes:'',partnerVersion:null,signedVersion:null,activity:[{text:'Plan prepared · illustrative',date:today}],created:new Date().toISOString()}}
if(!state.officePlansSeeded){const ready=newPlanObject({type:'startup',eis:'yes',name:'Example Robotics',amount:200000,date:today,years:'5',disposal:'2031-10-17',cross:true,sales:true,route:'personal',cadence:'once',policy:'reinvest'},'Ready to execute');ready.partnerNotes='Sample Partner note: use available cash first. Repay genuine loan principal, then sell only the personal fund amount needed. Confirm settled cash before subscribing. EIS eligibility, tax liability and connected-person tests require real checks before any live plan.';ready.partnerVersion=1;ready.signedVersion=1;ready.activity.push({text:'Sample Partner approval and client signature · not real authorisations',date:today});const draft=newPlanObject({type:'fund',eis:'no',name:'Long-term fund portfolio',amount:85000,date:'2026-11-02',years:'10',disposal:'',cross:true,sales:true,route:'split',cadence:'monthly',policy:'reinvest'});state.requests.push(ready,draft);state.officePlansSeeded=true;persist()}
let summaryYear='2026',holdingMeasure='value',filingTab='tasks';
function sectionNav(group,active){const choices=group==='wealth'?[['wealth','Overview'],['money','Holdings'],['tax','Tax & limits'],['assets','Other assets']]:group==='cashflow'?[['cashflow','Timeline'],['plans','Plans']]:[['filing','To do'],['files','Files']];return `<nav class="section-nav" aria-label="${group} sections">${choices.map(([id,label])=>`<a href="#${id}" ${id===active?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`}
function assetEquity(){return state.assets.reduce((a,x)=>a+Number(x.market)-Number(x.mortgage),0)}
function totalWealth(){return wealth()+assetEquity()}
function annualEvents(kind){const start=summaryYear+'-04-06',end=(Number(summaryYear)+1)+'-04-06';return state.journey.filter(e=>e.kind===kind&&e.date>=start&&e.date<end&&(kind!=='income'||e.owner==='Personal'))}
function annualSection(kind){const all=annualEvents(kind),total=all.reduce((a,e)=>a+(e.amount||0),0),up=all.filter(e=>e.date>=today),title={income:'Coming to you',tax:'Tax to pay',trade:'Planned transactions'}[kind];return `<section class="annual-section ${kind}-list"><div class="annual-heading"><h2>${{income:'↓',tax:'↑',trade:'⇄'}[kind]} ${title}</h2><strong>${money(total)}</strong></div><p class="annual-caption">${summaryYear}/${String(Number(summaryYear)+1).slice(2)} tax year · ${kind==='income'?'personal net receipts & loan repayments':kind==='tax'?'personal & company estimates':'purchase costs + sale proceeds, not net cash flow'}</p>${up.map(e=>`<button class="compact-event" data-event="${esc(e.id)}"><span><strong>${esc(e.name)}</strong><small>${when(e.date)} · ${esc(e.status)}</small></span><b>${money(e.amount)}</b></button>`).join('')||'<p class="muted">Nothing else recorded for this year.</p>'}<p class="fine">${money(all.filter(e=>e.date<today).reduce((a,e)=>a+(e.amount||0),0))} past events · ${money(up.reduce((a,e)=>a+(e.amount||0),0))} upcoming. Based on recorded timeline events; plan proposals are separate until confirmed.</p></section>`}
function yearPicker(){return `<div class="annual-picker"><span>Annual totals</span><div>${['2026','2027'].map(y=>`<button data-summary-year="${y}" aria-pressed="${summaryYear===y}">${y}/${String(Number(y)+1).slice(2)}</button>`).join('')}</div></div>`}
function wealthPage(){const financial=wealth(),equity=assetEquity(),change=financial-3220000;return `${sectionNav('wealth','wealth')}<section class="wealth-intro"><h1 class="eyebrow">Your wealth</h1><div class="wealth-number"><span>${money(totalWealth())}</span><i class="wealth-stop" aria-hidden="true"></i></div><button class="wealth-change" id="wealth-bridge">${change>=0?'+':'−'}${money(Math.abs(change))} this year <span>→</span></button><p class="muted wealth-context">${money(100000)} added · ${money(change-100000)} investment movement<br>Illustrative year-to-date record. Your home is included in wealth, never in investment funding.</p><div class="wealth-track"><span>Long-term target · illustrative, not a forecast</span><strong>${money(4100000)}</strong><div><i style="width:${Math.min(100,totalWealth()/4100000*100)}%"></i></div></div><button class="text-link" id="wealth-basis">${money(financial)} investments + ${money(equity)} other asset equity →</button></section><section class="invest-overview"><h2>Available to invest</h2><div class="available-figure">${money(spare())}<span>available cash</span></div><div class="money-pills"><button data-go="money"><i>£</i> ${money(cashTotal())} total cash ↗</button><button data-go="money"><i>↗</i> ${money(liquidInvestments())} investments to sell ↗</button><button data-go="tax"><i>◒</i> ${money(recAmount())} ISA space ↗</button></div><p class="investment-nudge">↗ ${money(recAmount())} of recorded ISA space to consider.</p><small class="muted">Illustrative opportunity. Eligibility, cash needs and suitability require Partner approval.</small><button class="primary make-investment" data-invest>Make investment <span>→</span></button></section><section class="planner-timeline"><div class="section-heading"><h2>Your timeline</h2><a class="text-link" href="#cashflow">Open cashflow →</a></div>${timeline()}</section>${yearPicker()}${annualSection('income')}${annualSection('tax')}${annualSection('trade')}<section>${dropZone()}</section><section><div class="section-heading"><h2>For you</h2><a href="#filing">Filing →</a></div>${reviewRows()}<a class="plan-shortcut" href="#plans">${state.requests.filter(r=>r.stage&&!['Executed','Rejected'].includes(r.stage)).length} investment plans in progress or awaiting action →</a></section><section class="home-asset"><h2>Your home & other assets</h2>${assetRows()}<button class="text-link" id="add-asset">Add an asset +</button></section>`}
function assetRows(){return state.assets.map(a=>`<button class="compact-event" data-asset="${esc(a.id)}"><span><strong>${esc(a.name)}</strong><small>${money(a.market)} value − ${money(a.mortgage)} debt${a.primary?' · primary home':''}</small></span><b>${money(a.market-a.mortgage)}<small>equity</small></b></button>`).join('')}
function assetsPage(){return `${sectionNav('wealth','assets')}<div class="page-heading"><h1>Other assets</h1><p>What you own, less what you owe.</p></div>${assetRows()}<p class="fine">Estimated equity before selling costs, tax and time to sell. This isn’t spendable cash. Your primary home is excluded from investment suggestions and funding.</p><button class="primary" id="add-asset">Add an asset +</button>`}
function cashflowPage(){return `${sectionNav('cashflow','cashflow')}<div class="page-heading"><h1>Cashflow</h1><p>Money coming in, money going out, and the steps in between.</p></div><section class="planner-timeline"><div class="section-heading"><h2>Your timeline</h2><button class="text-link" id="add-event">Add event +</button></div>${timeline()}</section>${yearPicker()}${annualSection('income')}${annualSection('tax')}${annualSection('trade')}<section>${holdingTimeline()}</section><section><div class="section-heading"><h2>Investment plans</h2><a href="#plans">See all →</a></div>${planRows()}</section><section><div class="section-heading"><h2>Travel</h2><button class="text-link" id="travel-plan">Add trip +</button></div><p>132 illustrative UK nights recorded. Additional itinerary: ${extraUKNights('Recorded')} recorded / ${extraUKNights('Planned')} planned calendar nights.</p><button class="text-link" data-event="review">Review the planned move & IHT position →</button><p class="fine">An itinerary is evidence, not a residence decision or a safe departure date.</p></section>`}
function holdingTimeline(){return `<div class="section-heading"><h2>What your holdings are doing</h2><div class="measure-switch"><button data-measure="value" aria-pressed="${holdingMeasure==='value'}">Value</button><button data-measure="shares" aria-pressed="${holdingMeasure==='shares'}">Units</button></div></div><div class="holding-years"><span>Now</span><span>2031</span><span>2036+</span></div>${['global','bonds','isa'].map(id=>{const p=ledger.positions.find(x=>x.id===id),policy=state.policies[id]||{mode:'reinvest',until:''};return `<button class="holding-band" data-policy="${id}"><div><strong>${esc(p.name)}</strong><span>${holdingMeasure==='value'?money(value(p)):p.qty.toLocaleString('en-GB')+' units'}</span></div><small>${esc(owners[p.owner])} · ${policy.mode==='income'?'Pay distributions':'Reinvest distributions'} · ${policy.until?'hold to '+when(policy.until):'ongoing'}</small><div class="holding-duration"><i style="width:${policy.until?Math.max(8,Math.min(100,(new Date(policy.until)-new Date(today))/315576000000*100)):100}%">${policy.mode==='income'?'●　●　●　●　→':'↻'}</i></div></button>`}).join('')}<p class="fine">Bar length shows intended holding time, not predicted growth. Dots show a recurring-income policy, not confirmed payments. Values and units are today’s sample records; actual distributions still need reconciliation.</p>`}
function planRows(){return state.requests.filter(r=>r.stage).map(r=>`<a class="plan-list-row" href="#plan/${r.id}"><span><strong>${esc(r.name)}</strong><small>${money(r.amount)} · ${when(r.date)} · ${r.scenario.legs.length} investment${r.scenario.legs.length>1?'s':''}</small></span><span class="plan-stage ${r.stage==='Executed'?'complete':''}">${esc(r.stage)}</span><span>→</span></a>`).join('')}
function plansPage(){return `${sectionNav('cashflow','plans')}<div class="section-heading"><h1>Investment plans</h1><button class="primary" data-invest>New plan +</button></div><p class="muted">Plan → Partner review → Your signature → Ready → Executed</p>${planRows()}<p class="fine">All workflow actions are local simulations. No broker, bank or DocuSign connection is active.</p>`}
function filingPage(){return `${sectionNav('filing','filing')}<div class="page-heading"><h1>Filing</h1><p>Your accountant prepares it. You check and approve.</p></div><section>${reviewRows()}</section><p class="fine">Sample drafts need professional completion. No tax return or company filing is submitted from this prototype.</p>`}
const officeMoney=moneyPage,officeTax=taxPage,officeFiles=filesPage;
window.ronScreens={home:wealthPage,wealth:wealthPage,cashflow:cashflowPage,plans:plansPage,assets:assetsPage,filing:filingPage,review:filingPage,money:()=>sectionNav('wealth','money')+officeMoney(),tax:()=>sectionNav('wealth','tax')+officeTax(),files:()=>sectionNav('filing','files')+officeFiles()};
function impactMarkup(s){const ids=[...new Set(s.parts.map(x=>x.source))];return `<details class="impact-detail" open><summary>Impact on your holdings</summary>${ids.map(id=>{const p=ledger.positions.find(x=>x.id===id),used=s.parts.filter(x=>x.source===id).reduce((a,x)=>a+x.gross,0);return `<div class="impact-row"><span>${esc(p.name)}<small>${esc(owners[p.owner])}${p.type!=='Cash'?' · '+(used/p.price).toLocaleString('en-GB',{maximumFractionDigits:3})+' units to sell':''}</small></span><span>${money(value(p))}<b>→ ${money(value(p)-used)}</b></span></div>`}).join('')}${s.parts.some(x=>x.transfer)?'<div class="impact-row"><span>Shareholder loan principal<small>Receivable and company debt change together</small></span><span>'+money(debt('fic'))+'<b>→ '+money(debt('fic')+s.parts.reduce((a,x)=>a+(x.transfer==='advance'?x.net:x.transfer==='repayment'?-x.net:0),0))+'</b></span></div>':''}<div class="impact-row"><span>New investment holdings</span><b class="positive">+${money(s.legs.reduce((a,l)=>a+l.amount,0))}</b></div><div class="impact-row"><span>Additional tax reserve & liability<small>Cash kept aside; not yet paid</small></span><b class="tax-number">${money(s.now)}</b></div><p class="fine">Projected net wealth impact: −${money(s.now)} in sale tax, before fees and market changes. Moving cash into investments or repaying an internal loan does not itself create new wealth. These projections do not change your recorded holdings.</p></details>`}
const legacyScenarioMarkup=scenarioMarkup;scenarioMarkup=function(s,p){if(!s.legs)return legacyScenarioMarkup(s,p);return `<div class="subscription-plan"><div class="subscription-header"><h3>${s.legs.length} separate investment${s.legs.length>1?'s':''}</h3><span>£${Number(p.amount).toLocaleString('en-GB')} total</span></div>${s.legs.map((l,i)=>`<div class="subscription-leg"><div class="subscription-title"><span class="leg-number">${i+1}</span><div><strong>${l.owner==='personal'?'You invest':'2LR Investments Ltd invests'}</strong><small>${l.isa?money(l.isa)+' via an eligible ISA':l.eisAmount?money(l.eisAmount)+' potentially EIS-eligible':'Direct holding · tax treatment to check'}</small></div><b>${money(l.amount)}</b></div>${s.parts.filter(x=>x.leg===i).map(x=>`<div class="funding-line"><span>${esc(x.label)}<small>${x.transfer==='repayment'?'Sell/settle if needed → repay loan principal → you':x.transfer==='advance'?'Your money → documented shareholder loan → company':x.kind==='sale'?'Sell → wait for settlement → invest':'Cash → invest'}</small></span><strong>${money(x.net)}</strong></div>`).join('')}</div>`).join('')}<div class="plan-tax-strip"><div><span>Tax triggered by sales</span><strong class="tax-number">${money(s.now)}</strong><small>Reserve now; pay when due</small></div><div><span>On a future 20% gain</span><strong>${money(s.future)}</strong><small>Before any EIS disposal relief or company withdrawal tax</small></div>${s.eis?`<div><span>Potential EIS relief</span><strong class="positive">Up to ${money(s.eis)}</strong><small>Not deducted; liability & eligibility unverified</small></div>`:''}</div>${!s.sameYear?'<p class="warning-note">Your recorded limits cover 2026/27. No ISA space, EIS headroom or personal gains exemption is assumed for this investment date. Update that year’s records with your Partner.</p>':''}${p.type==='startup'&&p.eis==='yes'?'<p class="fine">Company and personal stakes can affect EIS connected-person tests. A split is an option to investigate, not an automatic workaround for a used allowance. Eligibility and a minimum three-year holding period need review.</p>':''}${p.type==='startup'&&p.eis==='yes'&&Number(p.years)<3?'<p class="warning-note">A short holding period may lose EIS relief. Startup shares can also be hard to sell.</p>':''}${impactMarkup(s)}<details class="model-assumptions"><summary>Calculation & limits</summary><p>Recorded balances and prices as at 17 October 2026. Cash marked for tax, spending and commitments stays aside. Your primary home, private-company shares, property and ISA investments are never sold to fund this model.</p><p>Sale tax: 24% on sample personal gains after recorded remaining exemption, 25% on company gains. A proportional cost estimate is used; fees, losses, actual pooling and settlement prices aren’t modelled. Loans are principal, not deductible expenses. Each source is used only once across both investments.</p><p>Future scenario: a hypothetical 20% gain using today’s rates, no future annual gains exemption, eligible ISA gains sheltered. Income and future extraction tax from a company are excluded. EIS relief is conditional, needs enough Income Tax liability and is excluded from net costs. A higher knowledge-intensive limit and carry-back aren’t assumed.</p><p><a href="https://www.gov.uk/guidance/venture-capital-schemes-tax-relief-for-investors" target="_blank" rel="noopener">EIS rules ↗</a> · <a href="https://www.gov.uk/hmrc-internal-manuals/venture-capital-schemes-manual/vcm11080" target="_blank" rel="noopener">Connected-person rules ↗</a> · <a href="https://www.gov.uk/individual-savings-accounts" target="_blank" rel="noopener">ISA rules ↗</a></p></details></div>`};
function assetForm(id){const a=state.assets.find(x=>x.id===id)||{id:crypto.randomUUID(),name:'',market:0,mortgage:0,primary:false};open(`<h1>${id?'Your asset':'Add an asset'}</h1><form id="asset-form"><label for="asset-name">What is it?</label><input id="asset-name" value="${esc(a.name)}" required placeholder="Your home, a rental property, gold…"><label for="asset-value">Estimated current value (£)</label><input id="asset-value" type="number" min="0" step="1" required value="${a.market}"><label for="asset-debt">Mortgage or secured debt (£)</label><input id="asset-debt" type="number" min="0" step="1" required value="${a.mortgage}"><label class="check-line"><input type="checkbox" id="asset-home" ${a.primary?'checked':''}> This is my primary home</label><p class="fine">Equity is value less debt, before selling costs and tax. Your primary home is never suggested as investment funding. Add only assets not already recorded in your investment holdings.</p><button class="primary wide">Save asset</button></form>`);$('#asset-form').onsubmit=e=>{e.preventDefault();const item={...a,name:$('#asset-name').value.trim(),market:Number($('#asset-value').value),mortgage:Number($('#asset-debt').value),primary:$('#asset-home').checked};if(!item.name)return;const i=state.assets.findIndex(x=>x.id===a.id);if(i<0)state.assets.push(item);else state.assets[i]=item;persist();close();render()}}
function policyPage(id){const p=ledger.positions.find(x=>x.id===id),policy=state.policies[id];open(`<h1>${esc(p.name)}</h1><p>${esc(owners[p.owner])} · ${money(value(p))} · ${p.qty.toLocaleString('en-GB')} units</p><form id="policy-form"><fieldset><legend>What should distributions do?</legend><label class="check-line"><input name="policy" type="radio" value="reinvest" ${policy.mode==='reinvest'?'checked':''}> Reinvest in the fund</label><label class="check-line"><input name="policy" type="radio" value="income" ${policy.mode==='income'?'checked':''}> Pay regular income</label></fieldset><label for="hold-until">Hold until (leave blank for ongoing)</label><input id="hold-until" type="date" min="${today}" value="${policy.until}"><p class="fine">Sample gross annual yield: ${money(value(p)*p.yield/100)} at ${p.yield}%. Not guaranteed; tax treatment and actual distributions require review. A policy doesn’t place a reinvestment order.</p><button class="primary wide">Save holding intention</button></form>`);$('#policy-form').onsubmit=e=>{e.preventDefault();state.policies[id]={mode:document.querySelector('input[name="policy"]:checked').value,until:$('#hold-until').value};persist();close();render()}}
function findOfficePlan(id){return state.requests.find(r=>r.id===id&&r.stage)}
function planPage(r){const s=r.scenario,stage=r.stage;return `${backButton('plans')}<div class="plan-title"><p class="eyebrow">Investment plan · v${r.version} · illustrative</p><h1>${esc(r.name)}</h1><span class="plan-stage">${esc(stage)}</span></div><p class="plan-date">${money(r.amount)} · ${when(r.date)}${r.cadence!=='once'?' · '+esc(r.cadence)+' intention':''}</p><div class="lifecycle" aria-label="Plan lifecycle">${['Planned','Partner approved','Signed','Executing','Executed'].map((label,i)=>`<span class="${i===0||i===1&&r.partnerVersion===r.version||i===2&&r.signedVersion===r.version||i===3&&['In progress','Executed'].includes(stage)||i===4&&stage==='Executed'?'done':''}">${label}</span>`).join('')}</div><section class="partner-note"><h2>Partner’s notes</h2><p>${r.partnerNotes?esc(r.partnerNotes):'Awaiting review of investment suitability, ownership, liquidity and tax assumptions.'}</p></section><section><h2>The plan</h2><ol class="execution-list">${r.steps.map((step,i)=>`<li class="step-${step.status.toLowerCase()}"><span class="step-marker">${step.status==='Confirmed'?'✓':i+1}</span><div><strong>${esc(step.label)} <b>${money(step.amount)}</b></strong><p>${esc(step.detail)}</p><small>${esc(step.status)}</small></div></li>`).join('')}</ol></section>${stage==='Planned'?`<section class="demo-review"><h2>Partner review · demo controls</h2><label for="partner-notes">Review notes</label><textarea id="partner-notes" rows="4" placeholder="Explain the route, checks and any conditions…">${esc(r.partnerNotes)}</textarea><p class="fine">A real Partner must verify tax classifications, eligibility, affordability, liquidity, beneficiaries and account permissions. These controls only simulate that workflow.</p><div class="action-pair"><button class="primary" data-approve-plan="${r.id}">Approve sample plan</button><button class="secondary" data-reject-plan="${r.id}">Reject sample plan</button></div><p class="error" id="review-error" role="alert"></p></section>`:''}${stage==='Awaiting signature'?`<section class="authorise-block"><h2>Your approval comes next</h2><p>Review both subscriptions, every funding source and the sale tax reserve. Your signature applies to version ${r.version} only.</p><a class="primary action-link" href="#sign/${r.id}">Review & sign the plan →</a><small>DocuSign handoff concept · demo signature only</small></section>`:''}${stage==='Ready to execute'?`<section class="authorise-block"><p class="positive">✓ Partner-approved v${r.version}　✓ Client-signed v${r.version} · demo</p><h2>${r.date>today?'Ready for '+when(r.date):'Ready when you are'}</h2><p>Execution follows the steps in order. A confirmed sale and settled funds must arrive before a dependent transfer or purchase.</p><button class="execute-button" data-execute-plan="${r.id}" ${canExecutePlan(r)?'':'disabled'}>${r.date>today?'Schedule execution':'Execute plan'} <span>→</span></button><small>Simulation only. No funds move and no trades are sent.</small></section>`:''}${stage==='Scheduled'?`<section class="authorise-block"><h2>Scheduled for ${when(r.date)}</h2><p>No execution has started. A real connection would recheck balances, prices, permissions and the signed plan before starting.</p><button class="secondary" data-demo-due="${r.id}">Simulate scheduled date arriving</button></section>`:''}${stage==='In progress'?`<section class="execution-live"><h2>Execution in progress <i></i></h2><p>${esc(r.steps.find(s=>s.status==='Running')?.label||'Waiting for confirmation')}</p><p class="fine">Only one dependency step runs at a time. Unconfirmed or failed steps block later actions.</p><div class="action-pair"><button class="primary" data-confirm-step="${r.id}">Simulate confirmation →</button><button class="secondary" data-fail-step="${r.id}">Simulate failure</button></div></section>`:''}${stage==='Needs attention'?`<section class="warning-note"><h2>Stopped at a failed step</h2><p>Later instructions have not been sent. In a live system, reconcile the provider result before retrying to prevent duplicate transfers or orders.</p><button class="secondary" data-retry-step="${r.id}">Reconcile & retry (demo)</button></section>`:''}${stage==='Executed'?'<section class="intelligent-note"><h2>All steps confirmed · demo</h2><p>The simulated plan is complete. No real trade, transfer or tax payment occurred. Projected holdings remain separate from the current ledger.</p></section>':''}${stage==='Rejected'?'<p class="warning-note">Rejected. No signature or execution is available. Revise the plan to begin a fresh review.</p>':''}${!['In progress','Executed','Needs attention'].includes(stage)?`<button class="text-link" data-revise-plan="${r.id}">Change this plan →</button><p class="fine">Changes create a new version and invalidate the previous approval and signature.</p>`:''}<details class="plan-detail"><summary>Funding, tax & holdings impact</summary>${scenarioMarkup(s,r)}</details><section><h2>Approval & execution record</h2>${r.activity.map(a=>`<div class="audit-line"><span>${esc(a.text)}</span><small>${when(a.date)}</small></div>`).join('')}<p class="fine">Versioned demo record in this browser. A real service needs tamper-evident signed documents, verified provider confirmations and idempotent instructions.</p></section>${r.cadence!=='once'?'<p class="warning-note">Recurring intention: only the first instalment is covered by this plan. Future instalments require their own approval or an explicit standing mandate, funding checks and refreshed limits.</p>':''}`}
function signaturePage(r){return `${backButton('plan/'+r.id)}<p class="eyebrow">Client authorisation · demo</p><h1>Approve this exact plan</h1><p>${esc(r.name)} · version ${r.version} · ${when(r.date)}</p><div class="signature-document"><span class="report-ron">ron<span>.</span></span><h2>Investment instructions</h2><p>Investment total: <strong>${money(r.amount)}</strong></p>${r.scenario.legs.map(l=>`<p>${l.owner==='personal'?'Personal subscription':'Company subscription'}: <strong>${money(l.amount)}</strong></p>`).join('')}<h3>Source accounts</h3>${r.scenario.parts.map(x=>'<p>'+esc(x.label)+' → '+(x.to==='personal'?'personal investment':'company investment')+': '+money(x.net)+(x.transfer?' · shareholder loan '+(x.transfer==='repayment'?'repayment':'advance'):'')+'</p>').join('')}<p>Sale proceeds authorised: ${money(r.scenario.parts.filter(x=>x.kind==='sale').reduce((a,x)=>a+x.gross,0))}. Sale tax reserve: ${money(r.scenario.now)}.</p><p>Scope: the source accounts, transfers, subscriptions, amounts and sequence in plan version ${r.version}. One instalment only. No authority to use your home or reserved spending/tax cash.</p><p>No discretionary changes: a material change to amounts, assets, recipients, dates or funding requires a new review and signature. In live use, price tolerances, order limits, expiry, fees and cancellation terms must also be specified.</p><p>Partner’s notes: ${esc(r.partnerNotes)}</p><p class="fine">This is a sample authorisation document. It is not a DocuSign envelope or a legal signature.</p></div><label class="check-line"><input id="sign-confirm" type="checkbox"> I’ve reviewed this sample plan and its funding instructions.</label><button class="primary wide" data-sign-plan="${r.id}" disabled>Simulate signing · v${r.version}</button><p class="fine">In the product, DocuSign’s verified completion event would release the signed version for execution. No DocuSign connection is active here.</p>`}
window.ronDynamic=v=>{if(v.startsWith('plan/')){const r=findOfficePlan(v.slice(5));return r?planPage(r):backButton('plans')+'<h1>Plan not found</h1>'}if(v.startsWith('sign/')){const r=findOfficePlan(v.slice(5));return r&&r.stage==='Awaiting signature'&&r.partnerVersion===r.version?signaturePage(r):backButton('plans')+'<h1>A Partner-approved plan is needed first.</h1>'}return null};
const officeWizard=wizardPage,officeBindWizard=bindWizard;
invest=function(){plan={type:'',eis:'unknown',name:'',amount:12000,date:'2026-10-26',goal:'grow',years:'5',disposal:'',cross:true,sales:true,route:'auto',cadence:'once',policy:'reinvest'};navigate('invest/type')};
steps=function(){return ['type',plan.type==='startup'?'eis':'goal','amount','date','horizon',...(['fund','help'].includes(plan.type)?['policy']:[]),'funding','review']};
wizardPage=function(step){
 if(step==='date')return flowShell(step,'When are you investing?','We’ll use this date to check the right tax year and build the plan.',`<form id="investment-date-form"><label for="investment-date">Investment date</label><input id="investment-date" type="date" min="${today}" value="${plan.date||'2026-10-26'}" required><fieldset class="cadence-picker"><legend>Is this a one-off?</legend>${[['once','One-off'],['monthly','Monthly'],['quarterly','Quarterly']].map(([v,l])=>`<label><input name="cadence" type="radio" value="${v}" ${(plan.cadence||'once')===v?'checked':''}> ${l}</label>`).join('')}</fieldset><p class="fine">Recurring amounts describe your intention. This plan authorises the first instalment only.</p><button class="primary wide">Continue →</button></form>`);
 if(step==='policy')return flowShell(step,'Income or reinvestment?','Decide what distributions should do while you hold the fund.',choice('reinvest','Reinvest in the fund','Keep distributions invested.',plan.policy==='reinvest')+choice('income','Pay me the income','Plan to receive distributions as income.',plan.policy==='income'));
 if(step==='funding'){const options=compareRoutes(plan),s=chooseScenario(options,plan);return flowShell(step,'Here’s where it could come from.','Compare the ownership, the accounts funding it, and what you’d pay in tax.',`<div class="route-options">${options.map(r=>`<button data-route="${r.route}" class="route-choice ${s.route===r.route?'selected':''}"><span><strong>${r.title}</strong><small>${r.legs.map(l=>money(l.amount)+(l.owner==='personal'?' you':' company')).join(' + ')}</small><small>${r.shortfall>.01?money(r.shortfall)+' funding shortfall':money(r.now)+' sale tax · '+money(r.future)+' future-gain scenario'}</small></span><span>${r.route===s.route?'✓':'→'}</span></button>`).join('')}</div><details class="source-options"><summary>Choose permitted funding sources</summary><label class="check-line"><input id="flow-cross" type="checkbox" ${plan.cross?'checked':''}> Allow documented shareholder loan transfers</label><label class="check-line"><input id="flow-sales" type="checkbox" ${plan.sales?'checked':''}> Allow sales of the recorded personal & company equity funds</label></details>${scenarioMarkup(s,plan)}<p class="error">${s.shortfall>.01?'Needs '+money(s.shortfall)+' more funding. Change the amount or allowed sources.':''}</p><button class="primary wide" id="flow-to-review" ${s.shortfall>.01?'disabled':''}>Review plan →</button>`)}
 if(step==='review'){const s=chooseScenario(compareRoutes(plan),plan);return flowShell(step,'Review your investment','Your Partner reviews the strategy first. You sign the approved version before anything executes.',`<div class="plan-summary"><span>${esc(plan.name||'Fund investment')}</span><strong>${money(plan.amount)}</strong><p>${when(plan.date)} · ${plan.years} year horizon · ${plan.cadence||'once'}${['fund','help'].includes(plan.type)?' · '+(plan.policy==='income'?'pay distributions':'reinvest distributions'):''}</p></div>${scenarioMarkup(s,plan)}<section><h2>Execution sequence</h2><ol class="preview-steps">${executionSteps(s,plan).map(x=>`<li><strong>${esc(x.label)} · ${money(x.amount)}</strong><small>${esc(x.detail)}</small></li>`).join('')}</ol></section><button class="primary wide" id="office-save-plan">Save for Partner review →</button><p class="fine">Local demo only. No advice released, signature requested or instruction sent.</p>`)}
 let html=officeWizard(step);if(step==='horizon')html=html.replace('min="2026-10-18"','min="'+(plan.date||today)+'"');return html;
};
bindWizard=function(){officeBindWizard();if(!view().startsWith('invest/'))return;const step=view().split('/')[1];if(step==='amount')$('#flow-amount').onsubmit=e=>{e.preventDefault();plan.amount=Number($('#flow-sum').value);plan.name=$('#flow-name')?.value.trim()||'';if($('#flow-name')&&!plan.name)return;navigate('invest/date')};if(step==='date')$('#investment-date-form').onsubmit=e=>{e.preventDefault();plan.date=$('#investment-date').value;plan.cadence=document.querySelector('input[name="cadence"]:checked').value;if(plan.disposal&&plan.disposal<plan.date)plan.disposal='';navigate('invest/horizon')};if(step==='policy')document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{plan.policy=b.dataset.choice;navigate('invest/funding')});if(step==='horizon'){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{plan.years=b.dataset.choice;plan.disposal='';navigate(['fund','help'].includes(plan.type)?'invest/policy':'invest/funding')});$('#flow-date').onsubmit=e=>{e.preventDefault();const d=$('#flow-disposal').value;if(!d){$('#flow-disposal').required=true;$('#flow-disposal').reportValidity();return}plan.disposal=d;plan.years=String(Math.max(1,Math.round((new Date(d)-new Date(plan.date||today))/31557600000)));navigate(['fund','help'].includes(plan.type)?'invest/policy':'invest/funding')}}if($('#office-save-plan'))$('#office-save-plan').onclick=()=>{const r=newPlanObject(plan);if(r.scenario.shortfall>.01)return;const i=state.requests.findIndex(x=>x.id===plan.editId);if(i>=0){const previous=state.requests[i];r.id=previous.id;r.version=previous.version+1;r.activity=[...previous.activity,{text:'Plan revised: old approval and signature invalidated',date:today}];state.requests[i]=r}else state.requests.push(r);persist();navigate('plan/'+r.id);note('Plan saved locally. No Partner notification sent.')}};
const officeBaseBind=bind;
bind=function(){ensureOffice();officeBaseBind();const v=view(),group=['wealth','home','money','tax','assets'].includes(v)?'wealth':['cashflow','plans'].includes(v)||v.startsWith('plan/')||v.startsWith('sign/')||v.startsWith('invest/')?'cashflow':['filing','review','files'].includes(v)?'filing':null;document.querySelectorAll('header nav a').forEach(a=>{if(a.hash==='#'+group)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelectorAll('[data-summary-year]').forEach(b=>b.onclick=()=>{summaryYear=b.dataset.summaryYear;render()});document.querySelectorAll('[data-measure]').forEach(b=>b.onclick=()=>{holdingMeasure=b.dataset.measure;render()});document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>policyPage(b.dataset.policy));document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>assetForm(b.dataset.asset));if($('#add-asset'))$('#add-asset').onclick=()=>assetForm();if($('#wealth-basis'))$('#wealth-basis').onclick=()=>open(`<h1>Your wealth, counted once</h1><div class="plain-row"><span>Investment and company net wealth</span><strong>${money(wealth())}</strong></div><div class="plain-row"><span>Additional assets less their debts</span><strong>${money(assetEquity())}</strong></div><div class="plain-row"><span>Total</span><strong>${money(totalWealth())}</strong></div><p>Company equity is after company debts. Shareholder receivables and the corresponding company liabilities offset, so underlying assets aren’t counted twice.</p><p>Your home’s equity is included at estimated value before sale costs and tax. It is excluded from all investment funding suggestions.</p>`);if($('#wealth-bridge'))$('#wealth-bridge').onclick=()=>open(`<h1>What changed this year</h1><div class="plain-row"><span>Opening recorded investment wealth</span><strong>£3,220,000</strong></div><div class="plain-row"><span>Money added</span><strong>£100,000</strong></div><div class="plain-row"><span>Market & income movement</span><strong>${money(wealth()-3320000)}</strong></div><div class="plain-row"><span>Current recorded investment wealth</span><strong>${money(wealth())}</strong></div><p class="fine">Illustrative year-to-date bridge, not a time-weighted or money-weighted investment return. Additional assets are shown separately at their current estimated equity; adding an asset record isn’t investment profit. The £4.1m target is a sample goal, not a promised outcome.</p>`);
 document.querySelectorAll('[data-approve-plan],[data-reject-plan]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.approvePlan||b.dataset.rejectPlan),notes=$('#partner-notes').value.trim();if(!notes){$('#review-error').textContent='Add the Partner’s review notes first.';return}r.partnerNotes=notes;r.stage=b.dataset.approvePlan?'Awaiting signature':'Rejected';r.partnerVersion=b.dataset.approvePlan?r.version:null;r.signedVersion=null;r.activity.push({text:b.dataset.approvePlan?'Partner approved version '+r.version+' · demo':'Partner rejected version '+r.version+' · demo',date:today});persist();render()});if($('#sign-confirm'))$('#sign-confirm').onchange=e=>document.querySelector('[data-sign-plan]').disabled=!e.target.checked;document.querySelectorAll('[data-sign-plan]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.signPlan);if(!$('#sign-confirm').checked||r.partnerVersion!==r.version||r.stage!=='Awaiting signature')return;r.signedVersion=r.version;r.stage='Ready to execute';r.activity.push({text:'Client signed version '+r.version+' · simulated, not DocuSign',date:today});persist();navigate('plan/'+r.id)});
 document.querySelectorAll('[data-execute-plan]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.executePlan);if(!canExecutePlan(r))return;if(r.date>today){r.stage='Scheduled';r.activity.push({text:'Execution scheduled · demo',date:today})}else startExecution(r);persist();render()});document.querySelectorAll('[data-demo-due]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.demoDue);if(r.stage!=='Scheduled'||r.partnerVersion!==r.version||r.signedVersion!==r.version)return;startExecution(r);persist();render()});document.querySelectorAll('[data-confirm-step],[data-fail-step]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.confirmStep||b.dataset.failStep);if(advancePlanStep(r,!!b.dataset.failStep)){r.activity.push({text:b.dataset.failStep?'Step failed; subsequent instructions blocked · demo':'Step confirmation received · demo',date:today});persist();render()}});document.querySelectorAll('[data-retry-step]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.retryStep);if(r.stage!=='Needs attention')return;r.steps.find(s=>s.status==='Failed').status='Running';r.stage='In progress';r.activity.push({text:'Provider result reconciled; retry authorised · demo',date:today});persist();render()});document.querySelectorAll('[data-revise-plan]').forEach(b=>b.onclick=()=>{const r=findOfficePlan(b.dataset.revisePlan);if(['In progress','Executed','Needs attention'].includes(r.stage))return;plan={...structuredClone(r),editId:r.id,route:r.scenario.route};navigate('invest/amount')});document.querySelectorAll('[data-request]').forEach(b=>{if(findOfficePlan(b.dataset.request))b.onclick=()=>navigate('plan/'+b.dataset.request)});
};
function startExecution(r){r.stage='In progress';r.steps.find(s=>s.status==='Waiting').status='Running';r.activity.push({text:'Execution started; subsequent steps wait for confirmation · demo',date:today})}
// All detail and investment screens continue to use the shared back navigation.
const officeRender=render;render=function(){ensureOffice();const dynamic=window.ronDynamic(view());if(dynamic!==null){$('#screen').className='is-plan';$('#screen').innerHTML=dynamic;bind()}else{officeRender();if(!view().startsWith('detail/')&&!view().startsWith('invest/'))$('#screen').className=''}};
render();
// Plan proposals appear in the calendar, separate from reconciled cashflow totals.
window.ronDerivedEvents=function(){return state.requests.filter(r=>r.stage&&r.stage!=='Rejected').flatMap(r=>{const events=[];const occurrences=r.cadence==='once'?1:4;for(let n=0;n<occurrences;n++){const d=new Date(r.date+'T12:00:00Z'),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n*(r.cadence==='quarterly'?3:1));const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));for(const [i,l] of r.scenario.legs.entries())events.push({id:'plan@'+r.id+'@'+i+'@'+n,date:d.toISOString().slice(0,10),kind:'trade',name:r.name+' · '+(l.owner==='personal'?'personal':'company')+(n?' · repeat intention':''),owner:l.owner==='personal'?'Personal':'Company',amount:l.amount,status:n?'Proposed repeat · no standing mandate':r.stage+' · demo',note:'Investment plan proposal, not a reconciled trade. Open to review its funding and approval status.'})}if(r.disposal)events.push({id:'plan@'+r.id+'@disposal',date:r.disposal,kind:'trade',name:'Planned disposal: '+r.name,owner:r.scenario.legs.length>1?'Personal + company':r.scenario.legs[0].owner==='personal'?'Personal':'Company',amount:0,status:'Planned disposal · value unknown',note:'A target date, not a predicted sale price.'});return events})};
const recordedTimelineData=timelineData,recordedTimeline=timeline,recordedEventDetail=eventDetail;
timelineData=function(){const data=recordedTimelineData(),all=[...state.journey,...window.ronDerivedEvents()],end=journeyRange==='long'?all.flatMap(e=>[e.date,e.end||e.date]).sort().at(-1):data.end,start=journeyRange==='long'?'2026-09-01':data.start;return {start,end,events:all.filter(e=>(journeyFilter==='all'||e.kind===journeyFilter)&&e.date>=start&&e.date<=end).sort((a,b)=>a.date.localeCompare(b.date))}};
timeline=function(){return recordedTimeline().replace('Whole journey','2026–27 overview').replace('</select></label></div><svg','<option value="long" '+(journeyRange==='long'?'selected':'')+'>All planned years</option></select></label></div><svg')+'<p class="fine">Plan circles show proposals, including the next three recurring intentions. They are not included in the annual recorded-event totals until reconciled. Long-term disposals are available under “All planned years”.</p>'};
eventDetail=function(id){if(id.startsWith('plan@'))navigate('plan/'+id.split('@')[1]);else recordedEventDetail(id)};
render();
window.addEventListener('resize',()=>{if(['home','wealth','cashflow'].includes(view()))render()});
